req(all(sha(R/n)==h for n,h in c['sha256'].items()),'Closure bindings changed')
req(not git('diff','--cached','--name-only'),'Index not empty')
expected={str(p.relative_to(R)) for p in B.iterdir() if p.is_file()}|{pub}
